const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
nav?.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false')}});
const data=window.BIOTRACE;
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n};
if(data){
 const team=data.teams[data.activeYear],root=document.querySelector('#team');
 if(root){const bureau=el('div','bureau');if(team.bureauImage){const im=el('img');im.src=team.bureauImage;im.alt='Le bureau Biotrace '+data.activeYear;im.style.cssText='width:100%;max-width:430px;height:auto';bureau.append(im)}else{bureau.append(el('div','empty-media','Photo collective du bureau à intégrer'))}const text=el('div');text.append(el('span','tag','LE BUREAU '+data.activeYear),el('h3','','Les idées prennent vie en équipe.'),el('p','','Quatre pôles complémentaires pour coordonner, imaginer et faire avancer les projets de Biotrace.'));bureau.append(text);root.append(bureau);const grid=el('div','poles');team.poles.forEach((p,i)=>{const card=el('article','pole');card.style.background=p.color;const head=el('div','pole-head');head.append(el('span','tag','PÔLE 0'+(i+1)),el('h3','',p.name),el('p','',p.mission),el('blockquote','',p.quote));if(p.sheet){const img=el('img');img.src=p.sheet;img.alt='Fiche du pôle '+p.name;img.loading='lazy';img.style.width='100%';head.append(img)}card.append(head);const list=el('div','members');p.members.forEach(m=>{const member=el('article','member');if(m.portrait){const img=el('img');img.src=m.portrait;img.alt='Portrait de '+m.name;img.loading='lazy';img.width=148;img.height=288;img.className='portrait';member.append(img)}member.append(el('strong','',m.name));if(m.role)member.append(el('span','',m.role));list.append(member)});card.append(list,el('div','keywords',p.keywords));const files=['administration','tresorerie','communication','evenementiel'];const link=el('a','pole-poster','Voir la fiche du pôle ↗');link.href='assets/team/'+files[i]+'_affiche.jpg';link.target='_blank';link.rel='noopener';card.append(link);grid.append(card)});root.append(grid)}
 const gallery=document.querySelector('#gallery'),dialog=document.querySelector('#lightbox');if(gallery){if(!data.gallery.length){gallery.className='gallery-empty';gallery.append(el('p','','Le carnet attend vos photographies : congrès, stands et vie associative. Les vrais médias seront ajoutés ici dès leur réception.'))}else{data.gallery.forEach(item=>{const button=el('button');button.type='button';button.setAttribute('aria-label','Agrandir : '+item.alt);const img=el('img');img.src=item.src;img.alt=item.alt;img.loading='lazy';button.append(img);button.addEventListener('click',()=>{dialog.querySelector('img').src=item.src;dialog.querySelector('img').alt=item.alt;dialog.querySelector('p').textContent=item.caption||'';dialog.showModal()});gallery.append(button)})}dialog?.querySelector('button').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}
}
